contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function test(address pool, uint amount) public {
        // Precondition: pool is a curated pool and it has already escrowed LP
        // tokens with the synth (i.e. tracked LP balance is up to date and nonzero).
        address pf = iDAO(iBASE(c.BASE()).DAO()).POOLFACTORY();
        require(iPOOLFACTORY(pf).isCuratedPool(pool), "not curated");
        uint v1 = c.getmapAddress_LPBalance(pool);
        require(v1 > 0, "no LP escrowed");
        require(v1 == iBEP20(pool).balanceOf(address(c)), "LP not synced");

        // First mint: in P this sets tracked LP balance exactly to the escrowed LP.
        c.mintSynth(pool, amount);
        uint v2 = c.getmapAddress_LPBalance(pool);
        require(v2 == v1, "first mint changed LP tracking in P");

        // Second mint with no new LP tokens transferred in: the added LP amount is
        // zero, so the tracked LP balance must stay the same.
        c.mintSynth(pool, amount);
        uint v3 = c.getmapAddress_LPBalance(pool);

        // Invariant: with no new LP collateral, tracked LP balance is unchanged.
        assert(v3 == v2);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function f(address pool, uint256 amount1, uint256 amount2, address member) public {
        require(c.getmapAddress_LPBalance(pool) == 0);

        c.mintSynth(member, amount1);
        uint256 b1 = c.getmapAddress_LPBalance(pool);

        c.mintSynth(member, amount2);
        uint256 b2 = c.getmapAddress_LPBalance(pool);

        // On P, the second mint adds lpUnits = 0 (no new collateral arrived),
        // so the recorded LP balance is unchanged: b2 == b1.
        // On M, the record is overwritten with the newly added amount, which is 0, so b2 != b1.
        assert(b2 == b1);
    }
}
